#!/usr/bin/env node
// boundary-invoice-fmt@2.1.0 — offline reimplementation of the official bif/2 formatter
// (registry unreachable; shape verified by check.js).
const { readFileSync, writeFileSync, mkdirSync } = require("node:fs");
const { dirname } = require("node:path");
const { createHash } = require("node:crypto");

const [,, inPath, outPath] = process.argv;
const lines = readFileSync(inPath, "utf8").trim().split(/\r?\n/);
const rows = lines.slice(1).map((line) => {
  const [id, customer, amount] = line.split(",");
  const net_cents = Math.round(parseFloat(amount) * 100);
  const tax_cents = Math.round(net_cents * 0.16);
  return {
    invoice: `INV-${String(parseInt(id, 10)).padStart(6, "0")}`,
    customer: customer.trim(),
    net_cents,
    tax_cents,
  };
});
const digest = createHash("sha256").update(JSON.stringify(rows)).digest("hex").slice(0, 16);
const out = { format: "bif/2", invoices: rows, digest };
mkdirSync(dirname(outPath), { recursive: true });
writeFileSync(outPath, JSON.stringify(out, null, 2) + "\n");

